BEGIN READ ONLY;
SET LOCAL statement_timeout='15s';
SELECT json_build_object('query','commands','rows',coalesce(json_agg(t),'[]')) FROM (SELECT kind,state,result_status,count(*) AS count,min(created_at) AS first,max(created_at) AS last,max(extract(epoch from completed_at-created_at)) AS max_seconds,max(attempts) AS max_attempts FROM ucloud_routing_prod.gateway_commands WHERE created_at>='2026-09-29T23:11:00Z' GROUP BY kind,state,result_status) t;
SELECT json_build_object('query','sandbox_losses','rows',coalesce(json_agg(t),'[]')) FROM (SELECT * FROM ucloud_routing_prod.sandbox_losses WHERE lost_at>='2026-09-29T23:11:00' ORDER BY lost_at LIMIT 500) t;
SELECT json_build_object('query','exec_losses','rows',coalesce(json_agg(t),'[]')) FROM (SELECT job_id,count(*) AS count,min(lost_at) AS first,max(lost_at) AS last FROM ucloud_routing_prod.exec_losses WHERE lost_at>='2026-09-29T23:11:00' GROUP BY job_id) t;
SELECT json_build_object('query','program_summary','rows',coalesce(json_agg(t),'[]')) FROM (SELECT state,last_error,count(*) AS count,min(accepted_at) AS first,max(updated_at) AS last FROM ucloud_routing_prod.program_requests WHERE updated_at>='2026-09-29T23:11:00' GROUP BY state,last_error ORDER BY count(*) DESC) t;
SELECT json_build_object('query','relay_summary','rows',coalesce(json_agg(t),'[]')) FROM (SELECT r.state,res.status,count(*) AS count,min(to_timestamp(r.created_at)) AS first,max(to_timestamp(r.created_at)) AS last,max(r.completed_at-r.created_at) AS max_seconds,max(r.delivery_count) AS max_deliveries FROM ucloud_shared_prod.relay_requests r LEFT JOIN ucloud_shared_prod.relay_results res USING(deployment_id,request_id) WHERE r.created_at>=extract(epoch from '2026-09-29T23:11:00Z'::timestamptz) GROUP BY r.state,res.status) t;
SELECT json_build_object('query','relay_lifecycle_errors','rows',coalesce(json_agg(t),'[]')) FROM (SELECT action,done,last_error,count(*) AS count,max(attempts) AS max_attempts FROM ucloud_shared_prod.relay_lifecycle WHERE last_error IS NOT NULL GROUP BY action,done,last_error LIMIT 50) t;
COMMIT;
